import { Schema } from 'effect'

export const ApiSuccess = <T extends Schema.Top>(data: T) =>
  Schema.Struct({
    success: Schema.Literal(true),
    data,
  })

export const ApiFailure = Schema.Struct({
  success: Schema.Literal(false),
  error: Schema.String,
  issues: Schema.optional(Schema.Array(Schema.String)),
})
export type ApiFailure = typeof ApiFailure.Type

export const ApiEnvelope = <T extends Schema.Top>(data: T) =>
  Schema.Union([ApiSuccess(data), ApiFailure])

export const PaginatedResponse = <T extends Schema.Top>(item: T) =>
  Schema.Struct({
    success: Schema.Literal(true),
    data: Schema.Array(item),
    total: Schema.optional(Schema.NullOr(Schema.Number)),
    limit: Schema.Number,
    offset: Schema.Number,
    hasMore: Schema.Boolean,
    nextCursor: Schema.optional(Schema.NullOr(Schema.String)),
  })

export const PaginationParams = Schema.Struct({
  limit: Schema.optional(
    Schema.Number.check(Schema.isInt(), Schema.isBetween({ minimum: 1, maximum: 200 }))
  ),
  offset: Schema.optional(Schema.Number.check(Schema.isInt(), Schema.isGreaterThanOrEqualTo(0))),
  cursor: Schema.optional(Schema.String),
  include_total: Schema.optional(Schema.Boolean),
})
export type PaginationParams = typeof PaginationParams.Type
